fn solve(input: Vec<char>) -> Vec<char> {
    // Mapping from digit characters to their "good counts"
    let good_counts: [u8; 10] = [2, 7, 2, 3, 3, 4, 2, 5, 1, 2];

    // Extract the first two characters
    let first_digit = input[0];
    let second_digit = input[1];

    // Convert characters to their corresponding digit values
    let first_index = first_digit.to_digit(10).unwrap() as usize;
    let second_index = second_digit.to_digit(10).unwrap() as usize;

    // Calculate the product of the good counts
    let product = good_counts[first_index] * good_counts[second_index];

    // Convert the product to a string and create a character vector
    let result = format!("{}\n", product).chars().collect();

    result
}